function [CT,X,Y,Z,L,M,N] = BEMT(u,v,w,p,q,rho,CT,theta_0,theta_1c,theta_1s,rotor,geometry)

% Extract Parameters
Omega = geometry.Omega;
V_tip = geometry.Vtip;
c = geometry.cbar;
Nb = geometry.Nb;
R = geometry.R;
C_lalpha = geometry.CLalpha;
Cd0 = geometry.Cd0;
x_H = 3.2599 - geometry.flightCondition.xCG;
e = geometry.e;
m = geometry.m;
K_beta = geometry.K_beta;

% Normalise states
u_bar = u / V_tip;
v_bar = v / V_tip;
w_bar = w / V_tip;
p_hat = p / Omega;
q_hat = q / Omega;

% Select twist for each rotor
if rotor == 'upper'
    theta_tw = geometry.tw_u;
    z_H = 2.66847 - geometry.flightCondition.zCG + geometry.z_R;
else
    theta_tw = geometry.tw_l;
    z_H = 2.66847 - geometry.flightCondition.zCG;
end

% Inflow
[lambda_tot,lambda_0,lambda_1c,lambda_1s] = getInflow(u,v,w,CT,geometry);

% Flapping
[beta_0,beta_1c,beta_1s] = getFlappingResponse(u,v,p,q,rho,theta_0,theta_1c,theta_1s,theta_tw,lambda_tot,geometry);

Z = -(C_lalpha*Nb*Omega^2*R^3*c*rho*(4*theta_0 - 6*lambda_0 + 3*theta_tw + 6*w_bar - 3*lambda_1s*u_bar - 3*lambda_1c*v_bar + 3*p_hat*u_bar + 3*q_hat*v_bar + 6*theta_1s*u_bar + 6*theta_1c*v_bar + 6*theta_0*u_bar^2 + 3*theta_tw*u_bar^2 + 6*theta_0*v_bar^2 + 3*theta_tw*v_bar^2))/24;
X = (C_lalpha*Nb*Omega^2*R^3*c*rho*((pi*beta_1c*theta_0)/3 - pi*beta_1c*lambda_0 + (pi*beta_1c*theta_tw)/4 + pi*lambda_0*lambda_1s + pi*beta_1c*w_bar - pi*lambda_0*p_hat - (pi*lambda_0*theta_1s)/2 - (pi*lambda_1s*theta_0)/3 - (pi*lambda_1s*theta_tw)/4 - pi*lambda_1s*w_bar + (pi*p_hat*theta_0)/3 + (pi*p_hat*theta_tw)/4 + pi*p_hat*w_bar + (pi*theta_1s*w_bar)/2 - (pi*beta_1c^2*u_bar)/4 + (pi*beta_1s^2*u_bar)/4 - pi*lambda_0*theta_0*u_bar - (pi*lambda_1c*theta_1c*u_bar)/8 - (3*pi*lambda_1s*theta_1s*u_bar)/8 - (pi*lambda_0*theta_tw*u_bar)/2 - (pi*lambda_1c*theta_1s*v_bar)/8 - (pi*lambda_1s*theta_1c*v_bar)/8 + (3*pi*p_hat*theta_1s*u_bar)/8 + (pi*p_hat*theta_1c*v_bar)/8 + (pi*q_hat*theta_1c*u_bar)/8 - (pi*Cd0*u_bar)/C_lalpha + (pi*q_hat*theta_1s*v_bar)/8 + pi*theta_0*u_bar*w_bar + (pi*theta_tw*u_bar*w_bar)/2 + (pi*beta_0*beta_1s*u_bar^2)/2 + (3*pi*beta_0*beta_1s*v_bar^2)/2 - (pi*beta_0*theta_1c*u_bar^2)/4 - (pi*beta_1c*theta_0*u_bar^2)/4 - (pi*beta_1c*theta_tw*u_bar^2)/8 + (pi*beta_0*theta_1c*v_bar^2)/4 + (pi*beta_1c*theta_0*v_bar^2)/4 + (pi*beta_1c*theta_tw*v_bar^2)/8 + (pi*beta_1c*beta_1s*v_bar)/2 + (pi*beta_1c*lambda_1s*u_bar)/4 + (pi*beta_1s*lambda_1c*u_bar)/4 - 2*pi*beta_0*lambda_0*v_bar - (pi*beta_1c*lambda_1c*v_bar)/4 - (3*pi*beta_1s*lambda_1s*v_bar)/4 - (pi*beta_1c*p_hat*u_bar)/4 + (3*pi*beta_1s*p_hat*v_bar)/4 - (pi*beta_1s*q_hat*u_bar)/4 + (pi*beta_1c*q_hat*v_bar)/4 + (pi*beta_1c*theta_1s*u_bar)/4 - (pi*beta_1s*theta_1c*u_bar)/4 + (pi*beta_0*theta_0*v_bar)/2 + (pi*beta_1c*theta_1c*v_bar)/4 + (pi*beta_1s*theta_1s*v_bar)/4 + (pi*beta_0*theta_tw*v_bar)/3 + 2*pi*beta_0*v_bar*w_bar - pi*beta_0*beta_1c*u_bar*v_bar + (pi*beta_0*theta_1s*u_bar*v_bar)/2 + (pi*beta_1s*theta_0*u_bar*v_bar)/2 + (pi*beta_1s*theta_tw*u_bar*v_bar)/4))/(4*pi);
Y = -(C_lalpha*Nb*Omega^2*R^3*c*rho*((pi*beta_1s*theta_0)/3 - pi*beta_1s*lambda_0 + (pi*beta_1s*theta_tw)/4 - pi*lambda_0*lambda_1c + pi*beta_1s*w_bar + pi*lambda_0*q_hat + (pi*lambda_0*theta_1c)/2 + (pi*lambda_1c*theta_0)/3 + (pi*lambda_1c*theta_tw)/4 + pi*lambda_1c*w_bar - (pi*q_hat*theta_0)/3 - (pi*q_hat*theta_tw)/4 - pi*q_hat*w_bar - (pi*theta_1c*w_bar)/2 - (pi*beta_1c^2*v_bar)/4 + (pi*beta_1s^2*v_bar)/4 + (pi*lambda_1c*theta_1s*u_bar)/8 + (pi*lambda_1s*theta_1c*u_bar)/8 + pi*lambda_0*theta_0*v_bar + (3*pi*lambda_1c*theta_1c*v_bar)/8 + (pi*lambda_1s*theta_1s*v_bar)/8 + (pi*lambda_0*theta_tw*v_bar)/2 - (pi*p_hat*theta_1c*u_bar)/8 - (pi*p_hat*theta_1s*v_bar)/8 - (pi*q_hat*theta_1s*u_bar)/8 - (3*pi*q_hat*theta_1c*v_bar)/8 + (pi*Cd0*v_bar)/C_lalpha - pi*theta_0*v_bar*w_bar - (pi*theta_tw*v_bar*w_bar)/2 - (3*pi*beta_0*beta_1c*u_bar^2)/2 - (pi*beta_0*beta_1c*v_bar^2)/2 + (pi*beta_0*theta_1s*u_bar^2)/4 + (pi*beta_1s*theta_0*u_bar^2)/4 + (pi*beta_1s*theta_tw*u_bar^2)/8 - (pi*beta_0*theta_1s*v_bar^2)/4 - (pi*beta_1s*theta_0*v_bar^2)/4 - (pi*beta_1s*theta_tw*v_bar^2)/8 - (pi*beta_1c*beta_1s*u_bar)/2 - 2*pi*beta_0*lambda_0*u_bar - (3*pi*beta_1c*lambda_1c*u_bar)/4 - (pi*beta_1s*lambda_1s*u_bar)/4 + (pi*beta_1c*lambda_1s*v_bar)/4 + (pi*beta_1s*lambda_1c*v_bar)/4 + (pi*beta_1s*p_hat*u_bar)/4 - (pi*beta_1c*p_hat*v_bar)/4 + (3*pi*beta_1c*q_hat*u_bar)/4 - (pi*beta_1s*q_hat*v_bar)/4 + (pi*beta_0*theta_0*u_bar)/2 + (pi*beta_1c*theta_1c*u_bar)/4 + (pi*beta_1s*theta_1s*u_bar)/4 + (pi*beta_0*theta_tw*u_bar)/3 - (pi*beta_1c*theta_1s*v_bar)/4 + (pi*beta_1s*theta_1c*v_bar)/4 + 2*pi*beta_0*u_bar*w_bar + pi*beta_0*beta_1s*u_bar*v_bar + (pi*beta_0*theta_1c*u_bar*v_bar)/2 + (pi*beta_1c*theta_0*u_bar*v_bar)/2 + (pi*beta_1c*theta_tw*u_bar*v_bar)/4))/(4*pi);
L = (C_lalpha*Nb*Omega^2*R^3*c*rho*z_H*((pi*beta_1s*theta_0)/3 - pi*beta_1s*lambda_0 + (pi*beta_1s*theta_tw)/4 - pi*lambda_0*lambda_1c + pi*beta_1s*w_bar + pi*lambda_0*q_hat + (pi*lambda_0*theta_1c)/2 + (pi*lambda_1c*theta_0)/3 + (pi*lambda_1c*theta_tw)/4 + pi*lambda_1c*w_bar - (pi*q_hat*theta_0)/3 - (pi*q_hat*theta_tw)/4 - pi*q_hat*w_bar - (pi*theta_1c*w_bar)/2 - (pi*beta_1c^2*v_bar)/4 + (pi*beta_1s^2*v_bar)/4 + (pi*lambda_1c*theta_1s*u_bar)/8 + (pi*lambda_1s*theta_1c*u_bar)/8 + pi*lambda_0*theta_0*v_bar + (3*pi*lambda_1c*theta_1c*v_bar)/8 + (pi*lambda_1s*theta_1s*v_bar)/8 + (pi*lambda_0*theta_tw*v_bar)/2 - (pi*p_hat*theta_1c*u_bar)/8 - (pi*p_hat*theta_1s*v_bar)/8 - (pi*q_hat*theta_1s*u_bar)/8 - (3*pi*q_hat*theta_1c*v_bar)/8 + (pi*Cd0*v_bar)/C_lalpha - pi*theta_0*v_bar*w_bar - (pi*theta_tw*v_bar*w_bar)/2 - (3*pi*beta_0*beta_1c*u_bar^2)/2 - (pi*beta_0*beta_1c*v_bar^2)/2 + (pi*beta_0*theta_1s*u_bar^2)/4 + (pi*beta_1s*theta_0*u_bar^2)/4 + (pi*beta_1s*theta_tw*u_bar^2)/8 - (pi*beta_0*theta_1s*v_bar^2)/4 - (pi*beta_1s*theta_0*v_bar^2)/4 - (pi*beta_1s*theta_tw*v_bar^2)/8 - (pi*beta_1c*beta_1s*u_bar)/2 - 2*pi*beta_0*lambda_0*u_bar - (3*pi*beta_1c*lambda_1c*u_bar)/4 - (pi*beta_1s*lambda_1s*u_bar)/4 + (pi*beta_1c*lambda_1s*v_bar)/4 + (pi*beta_1s*lambda_1c*v_bar)/4 + (pi*beta_1s*p_hat*u_bar)/4 - (pi*beta_1c*p_hat*v_bar)/4 + (3*pi*beta_1c*q_hat*u_bar)/4 - (pi*beta_1s*q_hat*v_bar)/4 + (pi*beta_0*theta_0*u_bar)/2 + (pi*beta_1c*theta_1c*u_bar)/4 + (pi*beta_1s*theta_1s*u_bar)/4 + (pi*beta_0*theta_tw*u_bar)/3 - (pi*beta_1c*theta_1s*v_bar)/4 + (pi*beta_1s*theta_1c*v_bar)/4 + 2*pi*beta_0*u_bar*w_bar + pi*beta_0*beta_1s*u_bar*v_bar + (pi*beta_0*theta_1c*u_bar*v_bar)/2 + (pi*beta_1c*theta_0*u_bar*v_bar)/2 + (pi*beta_1c*theta_tw*u_bar*v_bar)/4))/(4*pi) - (Nb*beta_1s*(e*m*Omega^2*R^2 + 2*K_beta))/4;
M = (C_lalpha*Nb*Omega^2*R^3*c*rho*x_H*(4*theta_0 - 6*lambda_0 + 3*theta_tw + 6*w_bar - 3*lambda_1s*u_bar - 3*lambda_1c*v_bar + 3*p_hat*u_bar + 3*q_hat*v_bar + 6*theta_1s*u_bar + 6*theta_1c*v_bar + 6*theta_0*u_bar^2 + 3*theta_tw*u_bar^2 + 6*theta_0*v_bar^2 + 3*theta_tw*v_bar^2))/24 - (Nb*beta_1c*(e*m*Omega^2*R^2 + 2*K_beta))/4 + (C_lalpha*Nb*Omega^2*R^3*c*rho*z_H*((pi*beta_1c*theta_0)/3 - pi*beta_1c*lambda_0 + (pi*beta_1c*theta_tw)/4 + pi*lambda_0*lambda_1s + pi*beta_1c*w_bar - pi*lambda_0*p_hat - (pi*lambda_0*theta_1s)/2 - (pi*lambda_1s*theta_0)/3 - (pi*lambda_1s*theta_tw)/4 - pi*lambda_1s*w_bar + (pi*p_hat*theta_0)/3 + (pi*p_hat*theta_tw)/4 + pi*p_hat*w_bar + (pi*theta_1s*w_bar)/2 - (pi*beta_1c^2*u_bar)/4 + (pi*beta_1s^2*u_bar)/4 - pi*lambda_0*theta_0*u_bar - (pi*lambda_1c*theta_1c*u_bar)/8 - (3*pi*lambda_1s*theta_1s*u_bar)/8 - (pi*lambda_0*theta_tw*u_bar)/2 - (pi*lambda_1c*theta_1s*v_bar)/8 - (pi*lambda_1s*theta_1c*v_bar)/8 + (3*pi*p_hat*theta_1s*u_bar)/8 + (pi*p_hat*theta_1c*v_bar)/8 + (pi*q_hat*theta_1c*u_bar)/8 - (pi*Cd0*u_bar)/C_lalpha + (pi*q_hat*theta_1s*v_bar)/8 + pi*theta_0*u_bar*w_bar + (pi*theta_tw*u_bar*w_bar)/2 + (pi*beta_0*beta_1s*u_bar^2)/2 + (3*pi*beta_0*beta_1s*v_bar^2)/2 - (pi*beta_0*theta_1c*u_bar^2)/4 - (pi*beta_1c*theta_0*u_bar^2)/4 - (pi*beta_1c*theta_tw*u_bar^2)/8 + (pi*beta_0*theta_1c*v_bar^2)/4 + (pi*beta_1c*theta_0*v_bar^2)/4 + (pi*beta_1c*theta_tw*v_bar^2)/8 + (pi*beta_1c*beta_1s*v_bar)/2 + (pi*beta_1c*lambda_1s*u_bar)/4 + (pi*beta_1s*lambda_1c*u_bar)/4 - 2*pi*beta_0*lambda_0*v_bar - (pi*beta_1c*lambda_1c*v_bar)/4 - (3*pi*beta_1s*lambda_1s*v_bar)/4 - (pi*beta_1c*p_hat*u_bar)/4 + (3*pi*beta_1s*p_hat*v_bar)/4 - (pi*beta_1s*q_hat*u_bar)/4 + (pi*beta_1c*q_hat*v_bar)/4 + (pi*beta_1c*theta_1s*u_bar)/4 - (pi*beta_1s*theta_1c*u_bar)/4 + (pi*beta_0*theta_0*v_bar)/2 + (pi*beta_1c*theta_1c*v_bar)/4 + (pi*beta_1s*theta_1s*v_bar)/4 + (pi*beta_0*theta_tw*v_bar)/3 + 2*pi*beta_0*v_bar*w_bar - pi*beta_0*beta_1c*u_bar*v_bar + (pi*beta_0*theta_1s*u_bar*v_bar)/2 + (pi*beta_1s*theta_0*u_bar*v_bar)/2 + (pi*beta_1s*theta_tw*u_bar*v_bar)/4))/(4*pi);
N = (C_lalpha*Nb*Omega^2*R^4*c*rho*((pi*beta_1c^2)/4 + (pi*beta_1s^2)/4 + pi*lambda_0^2 + (pi*lambda_1c^2)/4 + (pi*lambda_1s^2)/4 + (pi*p_hat^2)/4 + (pi*q_hat^2)/4 + pi*w_bar^2 + (pi*beta_0^2*u_bar^2)/2 + (3*pi*beta_1c^2*u_bar^2)/8 + (pi*beta_1s^2*u_bar^2)/8 + (pi*beta_0^2*v_bar^2)/2 + (pi*beta_1c^2*v_bar^2)/8 + (3*pi*beta_1s^2*v_bar^2)/8 - (pi*beta_1c*lambda_1s)/2 + (pi*beta_1s*lambda_1c)/2 + (pi*beta_1c*p_hat)/2 - (pi*beta_1s*q_hat)/2 + (pi*beta_1c*theta_1s)/4 - (pi*beta_1s*theta_1c)/4 - (pi*lambda_1s*p_hat)/2 - (pi*lambda_1c*q_hat)/2 - (2*pi*lambda_0*theta_0)/3 - (pi*lambda_1c*theta_1c)/4 - (pi*lambda_1s*theta_1s)/4 - (pi*lambda_0*theta_tw)/2 - 2*pi*lambda_0*w_bar + (pi*p_hat*theta_1s)/4 + (pi*q_hat*theta_1c)/4 - (pi*Cd0)/(2*C_lalpha) + (2*pi*theta_0*w_bar)/3 + (pi*theta_tw*w_bar)/2 - (pi*lambda_0*theta_1s*u_bar)/2 - (pi*lambda_1s*theta_0*u_bar)/3 - (pi*lambda_1s*theta_tw*u_bar)/4 - (pi*lambda_0*theta_1c*v_bar)/2 - (pi*lambda_1c*theta_0*v_bar)/3 - (pi*lambda_1c*theta_tw*v_bar)/4 + (pi*p_hat*theta_0*u_bar)/3 + (pi*p_hat*theta_tw*u_bar)/4 + (pi*q_hat*theta_0*v_bar)/3 + (pi*q_hat*theta_tw*v_bar)/4 + (pi*theta_1s*u_bar*w_bar)/2 + (pi*theta_1c*v_bar*w_bar)/2 - (pi*beta_1c*theta_1s*u_bar^2)/8 - (pi*beta_1s*theta_1c*u_bar^2)/8 + (pi*beta_1c*theta_1s*v_bar^2)/8 + (pi*beta_1s*theta_1c*v_bar^2)/8 - (pi*Cd0*u_bar^2)/(2*C_lalpha) - (pi*Cd0*v_bar^2)/(2*C_lalpha) + (2*pi*beta_0*beta_1s*u_bar)/3 + (2*pi*beta_0*beta_1c*v_bar)/3 + (2*pi*beta_0*lambda_1c*u_bar)/3 + pi*beta_1c*lambda_0*u_bar - (2*pi*beta_0*lambda_1s*v_bar)/3 - pi*beta_1s*lambda_0*v_bar + (2*pi*beta_0*p_hat*v_bar)/3 - (2*pi*beta_0*q_hat*u_bar)/3 - (pi*beta_0*theta_1c*u_bar)/3 + (pi*beta_0*theta_1s*v_bar)/3 - pi*beta_1c*u_bar*w_bar + pi*beta_1s*v_bar*w_bar - (pi*beta_1c*beta_1s*u_bar*v_bar)/2 - (pi*beta_1c*theta_1c*u_bar*v_bar)/4 + (pi*beta_1s*theta_1s*u_bar*v_bar)/4))/(4*pi) - (C_lalpha*Nb*Omega^2*R^3*c*rho*x_H*((pi*beta_1s*theta_0)/3 - pi*beta_1s*lambda_0 + (pi*beta_1s*theta_tw)/4 - pi*lambda_0*lambda_1c + pi*beta_1s*w_bar + pi*lambda_0*q_hat + (pi*lambda_0*theta_1c)/2 + (pi*lambda_1c*theta_0)/3 + (pi*lambda_1c*theta_tw)/4 + pi*lambda_1c*w_bar - (pi*q_hat*theta_0)/3 - (pi*q_hat*theta_tw)/4 - pi*q_hat*w_bar - (pi*theta_1c*w_bar)/2 - (pi*beta_1c^2*v_bar)/4 + (pi*beta_1s^2*v_bar)/4 + (pi*lambda_1c*theta_1s*u_bar)/8 + (pi*lambda_1s*theta_1c*u_bar)/8 + pi*lambda_0*theta_0*v_bar + (3*pi*lambda_1c*theta_1c*v_bar)/8 + (pi*lambda_1s*theta_1s*v_bar)/8 + (pi*lambda_0*theta_tw*v_bar)/2 - (pi*p_hat*theta_1c*u_bar)/8 - (pi*p_hat*theta_1s*v_bar)/8 - (pi*q_hat*theta_1s*u_bar)/8 - (3*pi*q_hat*theta_1c*v_bar)/8 + (pi*Cd0*v_bar)/C_lalpha - pi*theta_0*v_bar*w_bar - (pi*theta_tw*v_bar*w_bar)/2 - (3*pi*beta_0*beta_1c*u_bar^2)/2 - (pi*beta_0*beta_1c*v_bar^2)/2 + (pi*beta_0*theta_1s*u_bar^2)/4 + (pi*beta_1s*theta_0*u_bar^2)/4 + (pi*beta_1s*theta_tw*u_bar^2)/8 - (pi*beta_0*theta_1s*v_bar^2)/4 - (pi*beta_1s*theta_0*v_bar^2)/4 - (pi*beta_1s*theta_tw*v_bar^2)/8 - (pi*beta_1c*beta_1s*u_bar)/2 - 2*pi*beta_0*lambda_0*u_bar - (3*pi*beta_1c*lambda_1c*u_bar)/4 - (pi*beta_1s*lambda_1s*u_bar)/4 + (pi*beta_1c*lambda_1s*v_bar)/4 + (pi*beta_1s*lambda_1c*v_bar)/4 + (pi*beta_1s*p_hat*u_bar)/4 - (pi*beta_1c*p_hat*v_bar)/4 + (3*pi*beta_1c*q_hat*u_bar)/4 - (pi*beta_1s*q_hat*v_bar)/4 + (pi*beta_0*theta_0*u_bar)/2 + (pi*beta_1c*theta_1c*u_bar)/4 + (pi*beta_1s*theta_1s*u_bar)/4 + (pi*beta_0*theta_tw*u_bar)/3 - (pi*beta_1c*theta_1s*v_bar)/4 + (pi*beta_1s*theta_1c*v_bar)/4 + 2*pi*beta_0*u_bar*w_bar + pi*beta_0*beta_1s*u_bar*v_bar + (pi*beta_0*theta_1c*u_bar*v_bar)/2 + (pi*beta_1c*theta_0*u_bar*v_bar)/2 + (pi*beta_1c*theta_tw*u_bar*v_bar)/4))/(4*pi);

CT = -Z / (rho*pi*R^2*Omega^2*R^2);

end